<?php require_once '../conexao.php';require_once '../includes/rbac.php';require_once '../includes/flash.php';exigirCargo(['recepcionista','administrador','diretor']);$prof=$pdo->query('SELECT id,nome,especialidade FROM profissionais WHERE ativo=1 ORDER BY nome')->fetchAll();$serv=['Psicoterapia','Fonoterapia infantil','Nutrição','Exame impedanciometria','Clínica geral'];if($_SERVER['REQUEST_METHOD']==='POST'){$nome=trim($_POST['nome']??'');$tel=trim($_POST['telefone']??'');$nasc=$_POST['nascimento']??'';$sv=$_POST['servico']??'';$pid=(int)($_POST['profissional_id']??0);$data=$_POST['data']??'';$hora=$_POST['horario']??'';try{if(!$nome||!$tel||!$nasc||!$sv||!$pid||!$data||!$hora)throw new Exception();$token=bin2hex(random_bytes(24));$s=$pdo->prepare("INSERT INTO agendamentos(nome,telefone,nascimento,servico,profissional_id,data,horario,status,token,criado_por) VALUES(?,?,?,?,?,?,?,'confirmado',?,?)");$s->execute([$nome,$tel,$nasc,$sv,$pid,$data,$hora.':00',$token,$_SESSION['usuario_id']]);flash('success','Consulta marcada pela recepção.');header('Location:index.php?data='.$data);exit;}catch(Throwable $e){flash('error','Não foi possível marcar. Confira os campos e se o horário está livre.');}}?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nova consulta | Aura</title><link rel="stylesheet" href="../css/style.css"></head><body><header class="header"><div class="container nav"><a href="index.php" class="brand"><img src="../img/logo-aura-oficial.png"></a><a href="index.php" class="back-link">← Agenda</a></div></header><main class="form-page"><div class="form-container"><p class="eyebrow">RECEPÇÃO</p><h1>Marcar consulta</h1><?php mostrarFlash();?><form method="post" class="form-card"><label>Paciente</label><input name="nome" required><label>Telefone</label><input name="telefone" required><label>Nascimento</label><input type="date" name="nascimento" required><label>Serviço</label><select name="servico" required><option value="">Selecione</option><?php foreach($serv as $v):?><option><?=$v?></option><?php endforeach;?></select><label>Profissional</label><select name="profissional_id" required><option value="">Selecione</option><?php foreach($prof as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['nome'])?></option><?php endforeach;?></select><label>Data</label><input type="date" name="data" min="<?=date('Y-m-d')?>" required><label>Horário</label><input type="time" name="horario" required><button class="btn btn-full">Marcar consulta</button></form></div></main><script src="../js/app.js"></script></body></html>
